package rand_test

import (
	"fmt"
	"math/rand"
	"testing"
)

// A seeded math/rand is a DETERMINISTIC sequence, and Go's compatibility
// promise covers it: "the sequence of values generated by a given Source
// is guaranteed to remain stable". Anything that reproduces a shuffle, a
// sample or a test fixture depends on that. A port whose generator
// differs by one step still returns numbers in range, so nothing looks
// wrong until two sides compare notes.
func TestGoishRef(t *testing.T) {
	for _, seed := range []int64{1, 42, 0, -1, 1 << 40} {
		r := rand.New(rand.NewSource(seed))
		fmt.Printf("int63 seed=%-14d", seed)
		for i := 0; i < 6; i++ {
			fmt.Printf(" %d", r.Int63())
		}
		fmt.Println()
	}
	r := rand.New(rand.NewSource(1))
	fmt.Printf("uint32 ")
	for i := 0; i < 6; i++ {
		fmt.Printf(" %d", r.Uint32())
	}
	fmt.Println()
	r = rand.New(rand.NewSource(1))
	fmt.Printf("uint64 ")
	for i := 0; i < 4; i++ {
		fmt.Printf(" %d", r.Uint64())
	}
	fmt.Println()
	r = rand.New(rand.NewSource(1))
	fmt.Printf("int31  ")
	for i := 0; i < 6; i++ {
		fmt.Printf(" %d", r.Int31())
	}
	fmt.Println()
	r = rand.New(rand.NewSource(1))
	fmt.Printf("int    ")
	for i := 0; i < 4; i++ {
		fmt.Printf(" %d", r.Int())
	}
	fmt.Println()

	for _, n := range []int64{1, 2, 10, 1000, 1 << 40} {
		r := rand.New(rand.NewSource(1))
		fmt.Printf("int63n %-14d", n)
		for i := 0; i < 6; i++ {
			fmt.Printf(" %d", r.Int63n(n))
		}
		fmt.Println()
	}
	for _, n := range []int32{1, 2, 10, 1000, 1 << 30} {
		r := rand.New(rand.NewSource(1))
		fmt.Printf("int31n %-14d", n)
		for i := 0; i < 6; i++ {
			fmt.Printf(" %d", r.Int31n(n))
		}
		fmt.Println()
	}
	for _, n := range []int{1, 2, 10, 1000} {
		r := rand.New(rand.NewSource(7))
		fmt.Printf("intn   %-14d", n)
		for i := 0; i < 6; i++ {
			fmt.Printf(" %d", r.Intn(n))
		}
		fmt.Println()
	}

	r = rand.New(rand.NewSource(1))
	fmt.Printf("float64")
	for i := 0; i < 5; i++ {
		fmt.Printf(" %v", r.Float64())
	}
	fmt.Println()
	r = rand.New(rand.NewSource(1))
	fmt.Printf("float32")
	for i := 0; i < 5; i++ {
		fmt.Printf(" %v", r.Float32())
	}
	fmt.Println()

	for _, n := range []int{0, 1, 5, 10} {
		r := rand.New(rand.NewSource(3))
		fmt.Printf("perm %-3d %v\n", n, r.Perm(n))
	}
	for _, n := range []int{0, 1, 5, 10} {
		r := rand.New(rand.NewSource(3))
		x := make([]int, n)
		for i := range x {
			x[i] = i
		}
		r.Shuffle(n, func(i, j int) { x[i], x[j] = x[j], x[i] })
		fmt.Printf("shuffle %-3d %v\n", n, x)
	}

	for _, n := range []int{0, 1, 7, 8, 9, 16} {
		r := rand.New(rand.NewSource(5))
		b := make([]byte, n)
		k, err := r.Read(b)
		fmt.Printf("read %-3d n=%d err=%v %v\n", n, k, err, b)
	}

	r = rand.New(rand.NewSource(1))
	fmt.Printf("norm  ")
	for i := 0; i < 5; i++ {
		fmt.Printf(" %v", r.NormFloat64())
	}
	fmt.Println()
	r = rand.New(rand.NewSource(1))
	fmt.Printf("exp   ")
	for i := 0; i < 5; i++ {
		fmt.Printf(" %v", r.ExpFloat64())
	}
	fmt.Println()

	// Seed on an existing Rand restarts the sequence.
	r = rand.New(rand.NewSource(1))
	a := r.Int63()
	r.Seed(1)
	fmt.Printf("reseed same=%v\n", r.Int63() == a)
}
